#!/usr/bin/env python3
"""Builds a stand-in main NSO for the lifter comparison (no game code): fake.cpp, plus generated C functions, compiled
for AArch64 with clang and linked by ld.lld into the NSO layout (MOD0 first, text / rodata / data at their offsets),
then packed as an NSO with an LZ4-compressed text segment, the way the console's files are.

    python3 make_fake.py <out.nso> [functions] [--seed N] [--extra <file.c|.s>]... [--ld <flag>]...

Needs clang and ld.lld with the AArch64 target and the Python lz4 package (developer machines and CI only).
"""
import hashlib
import os
import random
import struct
import subprocess
import sys
import tempfile

import lz4.block

HERE = os.path.dirname(os.path.abspath(__file__))


def gen_c(n, rnd):
    """n functions with switches, loops, float and integer math, calls between them and to imports"""
    out = ['/* generated by make_fake.py */', 'void ext_log(int); int ext_value(void); float ext_scale(float);',
           'typedef unsigned long u64; typedef long i64; typedef unsigned u32;']
    for i in range(n):
        out.append('i64 g%d(i64 a, u64 b, double d, float f);' % i)
    for i in range(n):
        body = []
        k = rnd.randrange(6)
        if k == 0:
            cases = ' '.join('case %d: a = a * %d + (i64)(b >> %d); %s break;' % (c, rnd.randrange(3, 99), rnd.randrange(1, 40),
                                                                          'ext_log(%d);' % c if rnd.random() < .5 else '')
                             for c in range(rnd.randrange(5, 12)))
            body.append('switch ((int)(b & 15)) { %s default: a ^= 0x%x; }' % (cases, rnd.getrandbits(31)))
        elif k == 1:
            body.append('for (int i = 0; i < (int)(b & 63); i++) { d = d * %r + f; f = f * 0.5f + (float)i; a += (i64)d; }' % (rnd.random() + .5))
        elif k == 2:
            body.append('u64 r = b; for (int i = 0; i < 8; i++) r = (r << %d) ^ (r >> %d) ^ (u64)a * 0x%xUL; a = (i64)r;'
                        % (rnd.randrange(1, 20), rnd.randrange(1, 20), rnd.getrandbits(48) | 1))
        elif k == 3:
            body.append('float v[8]; for (int i = 0; i < 8; i++) v[i] = f * (float)i + ext_scale((float)a); '
                        'for (int i = 0; i < 8; i++) d += v[i] * v[(i + 3) & 7]; a = (i64)(d * %r);' % rnd.random())
        elif k == 4:
            body.append('if (a < 0) return (i64)__builtin_sqrt(d < 0 ? -d : d) + (i64)(b %% %d); a = a / (i64)((b & 7) + 1) - (i64)(u32)b;'
                        % rnd.randrange(3, 1000))
        else:
            body.append('a += ext_value(); b ^= (u64)a << 3; d += (double)(u32)b / 7.0;')
        for _ in range(rnd.randrange(0, 3)):
            j = rnd.randrange(n)
            body.append('a += g%d(a ^ %d, b + %d, d * 0.75, f - 1.0f);' % (j, rnd.randrange(100), rnd.randrange(100))
                        if j > i else 'a -= (i64)b >> %d;' % rnd.randrange(1, 9))
        out.append('i64 g%d(i64 a, u64 b, double d, float f) { %s return a + (i64)d + (i64)f; }' % (i, ' '.join(body)))
    out.append('i64 (*const gtable[])(i64, u64, double, float) = {%s};' % ', '.join('g%d' % i for i in range(0, n, 3)))
    return '\n'.join(out) + '\n'


def build(out, nfuncs, seed, extra=(), ldflags=()):
    rnd = random.Random(seed)
    with tempfile.TemporaryDirectory() as t:
        with open(os.path.join(t, 'gen.c'), 'w') as f:
            f.write(gen_c(nfuncs, rnd))
        tgt = ['--target=aarch64-linux-gnu', '-fPIC', '-nostdinc', '-nostdlib', '-fno-builtin']
        objs = []
        for i, x in enumerate(extra):
            objs.append(os.path.join(t, 'extra%d.o' % i))
            subprocess.run(['clang'] + tgt + ['-O2', '-c', x, '-o', objs[-1]], check=True)
        for cmd in (['clang'] + tgt + ['-O2', '-fexceptions', '-c', os.path.join(HERE, 'fake.cpp'), '-o', os.path.join(t, 'fake.o')],
                    ['clang'] + tgt + ['-O2', '-c', os.path.join(t, 'gen.c'), '-o', os.path.join(t, 'gen.o')],
                    ['clang'] + tgt + ['-c', os.path.join(HERE, 'mod0.s'), '-o', os.path.join(t, 'mod0.o')],
                    ['ld.lld', '-shared', '--hash-style=sysv', '-T', os.path.join(HERE, 'link.ld'), '-z', 'norelro', '--eh-frame-hdr',
                     os.path.join(t, 'mod0.o'), os.path.join(t, 'fake.o'), os.path.join(t, 'gen.o')] + objs + list(ldflags)
                    + ['-o', os.path.join(t, 'fake.so')]):
            subprocess.run(cmd, check=True)
        elf = open(os.path.join(t, 'fake.so'), 'rb').read()
    phoff, = struct.unpack_from('<Q', elf, 0x20)
    phnum, = struct.unpack_from('<H', elf, 0x38)
    loads = []
    for i in range(phnum):
        typ, _, off, va, _, fsz, msz = struct.unpack_from('<IIQQQQQ', elf, phoff + i * 0x38)
        if typ == 1:
            loads.append((va, elf[off:off + fsz], msz))
    assert len(loads) == 3 and loads[0][0] == 0, 'expected text, rodata, data'
    segs = [bytearray(d) for _, d, _ in loads]
    segs[0] += bytes(-len(segs[0]) % 4)
    bss = loads[2][2] - len(loads[2][1])
    hdr = bytearray(0x100)
    hdr[0:4] = b'NSO0'
    struct.pack_into('<I', hdr, 12, 1)                   # flags: text LZ4-compressed
    pos = 0x100
    blobs = []
    for i, ((va, _, _), seg) in enumerate(zip(loads, segs)):
        stored = lz4.block.compress(bytes(seg), store_size=False) if i == 0 else bytes(seg)
        struct.pack_into('<III', hdr, 0x10 + 0x10 * i, pos, va, len(seg))
        struct.pack_into('<I', hdr, 0x60 + 4 * i, len(stored))
        hdr[0xA0 + 0x20 * i:0xC0 + 0x20 * i] = hashlib.sha256(bytes(seg)).digest()
        blobs.append(stored)
        pos += len(stored)
    struct.pack_into('<I', hdr, 0x3c, bss)
    hdr[0x40:0x60] = hashlib.sha256(b''.join(bytes(s) for s in segs)).digest()[:20] + bytes(12)
    with open(out, 'wb') as f:
        f.write(bytes(hdr) + b''.join(blobs))
    print('%s: text %d, rodata %d, data %d bytes' % (out, len(segs[0]), len(segs[1]), len(segs[2])))


if __name__ == '__main__':
    a = sys.argv[1:]
    seed, extra, ldflags = 1, [], []
    for opt, dst in (('--seed', None), ('--extra', extra), ('--ld', ldflags)):
        while opt in a:
            k = a.index(opt)
            if dst is None:
                seed = int(a[k + 1])
            else:
                dst.append(a[k + 1])
            del a[k:k + 2]
    build(a[0], int(a[1]) if len(a) > 1 else 300, seed, extra, ldflags)
